 function sequenceSaved(){try{return JSON.parse(sessionStorage.getItem(sequenceMode==='development'?developmentJournal:sequenceMode==='expanded'?expandedJournal:sequenceJournal)||'null');}catch{throw Error('Invalid saved sequence');}}
 async function sequenceFor(plan,fence){let seq=sequenceSaved();if(seq){if(!sameScope(seq.scope,fence.scope)||seq.runtime!==fence.runtime||!/^sequence_[a-f0-9]{32}$/.test(seq.id))throw Error('Sequence scope changed');await trialCall('sequenceStatus',{planId:plan.id,expectedRevision:plan.revision,sequenceId:seq.id});assertTrialFence(fence);return seq.id;}seq={scope:fence.scope,runtime:fence.runtime,id:sequenceMode==='development'?configurationSaved()?.sequenceIntentId:'sequence_'+crypto.randomUUID().replaceAll('-',''),registrationRequested:true};sessionStorage.setItem(sequenceMode==='development'?developmentJournal:sequenceMode==='expanded'?expandedJournal:sequenceJournal,JSON.stringify(seq));const configuration=sequenceMode==='development'?configurationSaved():null;if(sequenceMode==='development'&&(!configuration||configuration.status!=='verified'||configuration.sequenceIntentId!==seq.id))throw Error('Verified configuration intent required');await trialCall('sequenceRegister',{planId:plan.id,expectedRevision:plan.revision,sequenceId:seq.id,expiresAt:Date.now()+(['expanded','development'].includes(sequenceMode)?86400000:3600000),...(configuration?{configurationIntentId:configuration.id}:{})});assertTrialFence(fence);return seq.id;}
 function trialFence(){return{epoch:scopeEpoch,scope:{...data.scopeIdentity},runtime:JSON.stringify(data.runtime)};}
 expandedEnroll.addEventListener('click',async()=>{if(!data||busy||trialBusy||sequenceMode!=='expanded')return;const fence=trialFence();trialBusy=true;try{const seq=sequenceSaved(),plans=data.plans.filter(p=>p.objective===expandedObjective&&p.status==='queued'&&p.engineeringProfile==='engineering-inference-rehearsal-v1'&&p.tasks.every(t=>t.attempts.length===0));if(!seq||!sameScope(seq.scope,fence.scope)||plans.length!==1)throw Error('Exact expanded scope required');const result=await trialCall('sequenceEnroll',{planId:plans[0].id,expectedRevision:plans[0].revision,sequenceId:seq.id});assertTrialFence(fence);seq.runtime=fence.runtime;sessionStorage.setItem(expandedJournal,JSON.stringify(seq));trialResult.textContent=JSON.stringify({enrollment:result,paidRequestStarted:false},null,2);}catch{if(currentTrialFence(fence))trialResult.textContent='Release enrollment unconfirmed. Inspect the authoritative sequence; do not run or retry registration.';}finally{trialBusy=false;}});
 function currentTrialFence(f){return f&&data&&f.epoch===scopeEpoch&&sameScope(f.scope,data.scopeIdentity)&&f.runtime===JSON.stringify(data.runtime);}
 function assertTrialFence(f){if(!currentTrialFence(f))throw Error('Engineering trial context changed');}
 async function revokeSaved(saved){const a=saved.input.approval;return trialCall('revoke',{planId:saved.input.planId,approvalId:a.id,approvalHash:await digest(a)});}
 trialPrepare.addEventListener('click',async()=>{if(!data||busy||trialBusy)return;const prior=trialSaved();if(prior){trialResult.textContent='Saved trial exists. Inspect or revoke it; preparation is never retried automatically.';return;}const selectedObjective=implementationLiveMode?data.organization.implementationPreparation?.objective:sequenceMode==='expanded'?expandedObjective:sequenceMode?sequenceObjective:trialObjective;const plans=data.plans.filter(p=>p.objective===selectedObjective&&p.status==='queued'&&p.engineeringProfile===(implementationLiveMode?'engineering-implementation-v1':'engineering-inference-rehearsal-v1')&&p.tasks.every(t=>t.attempts.length===0));if(plans.length!==1){trialResult.textContent='Exactly one fresh authorized admission manifest is required.';return;}trialBusy=true;const fence=trialFence();let saved,preparationPhase='sequence-resolution';try{const sequenceId=(sequenceMode==='development'||[sequenceObjective,expandedObjective].includes(plans[0].objective))?await sequenceFor(plans[0],fence):null;preparationPhase='trial-manifest';const proposal=await trialCall('trial-manifest',{planId:plans[0].id,expectedRevision:plans[0].revision,...(sequenceId?{sequenceId}:{})});assertTrialFence(fence);saved={scope:fence.scope,input:{planId:proposal.planId,expectedRevision:proposal.expectedRevision,approval:proposal.approval},requested:false};if(!trialScope(saved))throw Error('Scope changed');trialSave(saved);preparationPhase='prepare';const prepared=await trialCall('prepare',saved.input);assertTrialFence(fence);saved.expectedApprovalRevision=prepared.record.revision;trialSave(saved);trialResult.textContent=JSON.stringify({input:saved.input,prepared:prepared.record,paidRequestStarted:false},null,2);}catch(error){if(saved)try{await revokeSaved(saved);}catch{}if(currentTrialFence(fence))trialResult.textContent='Preparation unconfirmed. Do not repeat. Revoke saved engineering trial and inspect durable owner history. Phase: '+(preparationPhases.has(error?.safePreparationPhase)?error.safePreparationPhase:preparationPhase)+'. Code: '+(preparationFailureCodes.has(error?.safePreparationCode)?error.safePreparationCode:'ENG_PREPARATION_UNCONFIRMED')+'. No paid dispatch was requested by preparation.';}finally{trialBusy=false;}});
 trialRun.addEventListener('click',async()=>{if(trialBusy||busy)return;const saved=trialSaved();if(!trialScope(saved)||saved.requested||!Number.isSafeInteger(saved.expectedApprovalRevision)){trialResult.textContent='No fresh prepared trial available. A requested trial cannot be retried.';return;}const fence=trialFence();trialBusy=true;saved.requested=true;try{trialSave(saved);const activated=await trialCall('activate',{...saved.input,expectedApprovalRevision:saved.expectedApprovalRevision});assertTrialFence(fence);trialResult.textContent='One authorized trial running. Do not repeat or close this page; cancellation and revocation remain available.';const result=await trialCall('run',{...saved.input,expectedApprovalRevision:activated.revision},650000);assertTrialFence(fence);saved.finished=true;trialSave(saved);trialResult.textContent=JSON.stringify(result,null,2);}catch{if(currentTrialFence(fence))trialResult.textContent='Trial stopped or delivery unconfirmed. No automatic retry. Inspect owner workflow receipts and retained uncertainty; no acceptance or publication is inferred.';}finally{try{const closed=await revokeSaved(saved);if(currentTrialFence(fence))trialResult.textContent+='\nShutdown readback: '+JSON.stringify(closed);}catch{if(currentTrialFence(fence))trialResult.textContent+='\nRevocation unconfirmed: use Revoke saved engineering trial and owner emergency stop; do not retry execution.';}trialBusy=false;}});
 sequenceStop.addEventListener('click',async()=>{if(!data||busy||trialBusy)return;const fence=trialFence();try{const seq=sequenceSaved();if(!seq||!sameScope(seq.scope,fence.scope))return;const result=await trialCall('sequenceStop',{sequenceId:seq.id});assertTrialFence(fence);trialResult.textContent+='\nBounded sequence stopped: '+JSON.stringify(result);}catch{if(currentTrialFence(fence))trialResult.textContent+='\nSequence stop unconfirmed. Revoke current trial authority first; do not retry paid execution.';}});
