 configPanel.append(node('summary','Developer: Preview refresh evidence'),node('p','Exact non-secret configuration intent only. Persist the claim before provider mutation, record dispatch before each operation, and reconcile unknown acknowledgments without retrying. Credentials are never entered here. Completion requires actual deployed metadata and future flags reset.'),configInput,configResult);
 configInput.id='opsEngineeringConfigurationInput';configInput.maxLength=16000;configInput.setAttribute('aria-label','Non-secret reviewed configuration receipt input');configResult.id='opsEngineeringConfigurationResult';
 for(const method of ['cleanupReconcile','configurationClaim','configurationStep','configurationStatus','configurationComplete','configurationCancel','configurationRejectionReconcile']){const button=node('button',method);button.type='button';button.id='opsEngineering'+method;configPanel.append(button);button.addEventListener('click',async()=>{if(!data||busy||trialBusy)return;const fence=trialFence();let intentId=null;trialBusy=true;try{const input=JSON.parse(configInput.value);if(JSON.stringify(input).length>16000||/OPENAI_API_KEY|authorization.?header|Bearer\s|sk-proj-/i.test(configInput.value))throw Error('Secrets forbidden');const candidate=input?.intent?.id||input?.id;if(/^refresh_[a-f0-9]{32}$/.test(candidate||''))intentId=candidate;if(method==='configurationClaim'||method==='configurationCancel'||method==='configurationRejectionReconcile'){sessionStorage.setItem(configurationJournal+'-pending',JSON.stringify({scope:fence.scope,runtime:fence.runtime,input}));}const result=await trialCall(method,input);assertTrialFence(fence);if(!['cleanupReconcile','configurationRejectionReconcile'].includes(method))sessionStorage.setItem(configurationJournal,JSON.stringify(result));configResult.textContent=JSON.stringify(result,null,2);}catch(error){if(currentTrialFence(fence))configResult.textContent='Operation unconfirmed. Inspect the durable intent by ID before any provider mutation or retry. No automatic retry, configuration change or paid request occurred in this control.'+(configurationFailureCodes.has(error?.safeConfigurationCode)?' Code: '+error.safeConfigurationCode+'.':'')+(intentId?' Intent: '+intentId+'.':'');}finally{trialBusy=false;if(data)render(data);}});}
 developmentPreset.type=developmentEnroll.type='button';developmentPreset.id='opsEngineeringDevelopmentPreset';developmentEnroll.id='opsEngineeringDevelopmentEnroll';trialPanel.append(node('p','Reviewed implementation allowance: at most ten serial trials share $4 from the existing unused allowance. Exact configuration evidence and reviewed release enrollment are mandatory. Internal exposure is not a provider billing cap.'),developmentPreset,developmentEnroll,configPanel);
