 async function digest(x){const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(x)));return [...new Uint8Array(bytes)].map(b=>b.toString(16).padStart(2,'0')).join('');}
 trialRevoke.addEventListener('click',async()=>{const saved=trialSaved();if(!saved||!data||!sameScope(saved.scope,data.scopeIdentity))return;const fence=trialFence();try{const result=await revokeSaved(saved);assertTrialFence(fence);trialResult.textContent+='\nExplicit revocation: '+JSON.stringify(result);if(!trialBusy&&['owner-expanded-engineering-5usd-v1','owner-phase-d-engineering-4usd-v1'].includes(saved.input.approval.countPricing?.authorizationId)&&result.status==='revoked'&&result.leaseUntil===0){const journal=saved.input.approval.countPricing.authorizationId==='owner-phase-d-engineering-4usd-v1'?developmentAttemptJournal:expandedAttemptJournal,key=journal+'-history',history=JSON.parse(sessionStorage.getItem(key)||'[]');if(!Array.isArray(history)||history.length>=20)throw Error('Attempt archive bounded');history.push({saved,revocation:result});sessionStorage.setItem(key,JSON.stringify(history));sessionStorage.removeItem(journal);trialResult.textContent+='\nClosed attempt archived locally; authoritative evidence remains in the server journal. A new paid attempt still requires fresh admission and backend limits.';}}catch{if(currentTrialFence(fence))trialResult.textContent+='\nRevocation or local archive unconfirmed; inspect authoritative owner status.';}});

